"""Add Pneumocystis and cerebral toxoplasmosis to the HIV chapter."""
from create_hiv_art import rows,q,DX,AR,MO,HB,AB,UU,IN
from qbank_authoring import ref,finalize
PC=ref('NIH: Pneumocystis Pneumonia, Adult and Adolescent OIs','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/pneumocystis')
TO=ref('NIH: Toxoplasma gondii Encephalitis','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/toxoplasmosis')
q('An untreated patient with HIV has CD4 65, progressive dry cough, exertional dyspnea and diffuse bilateral ground-glass opacity. Which infection is most likely?', 'Pneumocystis jirovecii pneumonia',[
 ('Pneumococcal lobar pneumonia','It more often has an acute focal consolidation, though overlap is possible.'),('Pulmonary tuberculosis as the only possible cause','TB remains a differential, but this subacute diffuse hypoxemic pattern strongly suggests PCP.'),('Isolated CMV viremia as proof of CMV pneumonitis','Blood detection alone does not establish CMV lung disease.')],
 'Advanced cellular immunodeficiency changes the pneumonia differential', '**PCP commonly produces a subacute dry cough and hypoxemic diffuse lung disease.**',['A normal early chest radiograph does not exclude it.','LDH and beta-D-glucan can support suspicion but are nonspecific.'], '**Obtain appropriate respiratory testing while treating a high-probability severe illness.**',['Assess oxygenation and need for adjunctive steroids.','Investigate coexisting infections when the presentation or course warrants it.'],[['Pattern','Subacute diffuse hypoxemic pneumonia'],['Risk','Advanced untreated HIV'],['Confirmation','Appropriate respiratory organism testing']],[PC],style='clinical_scenario')
q('What is the preferred first-line treatment for most HIV-associated PCP when tolerated?', 'Trimethoprim-sulfamethoxazole for a 21-day treatment course',[
 ('Fluconazole alone','It is not an effective PCP treatment.'),('Azithromycin alone','It does not adequately treat PCP.'),('Low-dose prophylactic TMP-SMX without therapeutic escalation','The treatment dose differs from prophylaxis.')],
 'Prophylaxis and treatment require different exposure', '**TMP-SMX is the preferred PCP treatment.**',['Select route and dose according to severity, weight and organ function.','Monitor renal function, potassium, cytopenias and hypersensitivity.'], '**Assess response over an appropriate interval.**',['Early clinical worsening can occur and requires evaluation.','Severe toxicity or failure may require an alternative regimen and specialist review.'],[['Preferred drug','TMP-SMX'],['Duration in HIV','21 days'],['Monitoring','Renal, potassium, blood count and rash']],[PC])
q('A patient with HIV-associated PCP has room-air PaO2 62 mmHg. Which adjunct is indicated?', 'Systemic corticosteroids started promptly, ideally within 72 hours of PCP therapy',[
 ('Steroids only after the 21-day antibiotic course is complete','The benefit is associated with early use in qualifying hypoxemia.'),('No steroids because PCP is an infection','Moderate-to-severe HIV-associated PCP is a specific evidence-based indication.'),('Steroids alone without anti-Pneumocystis treatment','They do not eradicate the organism.')],
 'Hypoxemia identifies the PCP group benefiting from adjunctive steroids', '**The usual criterion is PaO2 below 70 mmHg or A–a gradient at least 35 mmHg on room air.**',['Use the recommended tapering regimen.','Continue effective anti-Pneumocystis therapy.'], '**Assess respiratory deterioration urgently.**',['Exclude pneumothorax and coexisting processes when appropriate.','Monitor glucose and other steroid adverse effects.'],[['PaO2','Below 70 mmHg'],['Alternative criterion','A–a gradient ≥35'],['Timing','Ideally within 72 hours']],[PC],style='clinical_scenario')
q('A person with HIV is on ART and has CD4 75 despite currently suppressed plasma HIV RNA. What is the PCP primary-prophylaxis implication?', 'Prophylaxis is indicated at CD4 below 100 regardless of viral load',[
 ('Suppression always removes the indication even below 100','This is not the current threshold recommendation.'),('Only give prophylaxis if CD4 falls below 20','This misses an important prevention window.'),('Use a live PCP vaccine instead','No such preventive vaccine replaces prophylaxis.')],
 'The lowest CD4 stratum remains high risk despite suppression', '**NIH recommends prophylaxis below CD4 100 regardless of HIV RNA.**',['At counts 100–200, viral-load context influences the recommendation.','TMP-SMX is preferred when suitable.'], '**Review tolerance and recovery over time.**',['Evaluate alternative regimens when necessary.','Discontinuation requires the appropriate immune and virological recovery criteria.'],[['CD4 <100','Prophylaxis regardless of viral load'],['CD4 100–200 on ART','Viremia context matters'],['Preferred','TMP-SMX when suitable']],[PC])
q('A patient with advanced HIV cannot use TMP-SMX and is being considered for dapsone-based PCP prophylaxis. Which baseline test is important?', 'G6PD activity',[
 ('HLA-B*5701 as the specific dapsone hemolysis test','That is the abacavir-specific hypersensitivity marker.'),('Serum troponin to rule out all dapsone toxicity','It does not assess susceptibility to oxidant hemolysis.'),('INR as a reliable measure of G6PD function','These assess different biological processes.')],
 'Alternative prophylaxis has its own safety requirements', '**Dapsone can cause hemolysis and methemoglobinemia.**',['G6PD deficiency increases oxidant hemolysis risk.','A normal result does not eliminate every possible adverse effect.'], '**Select an appropriate alternative if deficient.**',['Primaquine also requires G6PD assessment before use.','Consider Toxoplasma serostatus when choosing a prophylactic regimen.'],[['Dapsone','Oxidant adverse effects'],['G6PD','Safety assessment'],['Regimen choice','Also consider Toxoplasma coverage']],[PC])
q('Which respiratory diagnostic principle is correct for suspected PCP?', 'Induced sputum or BAL testing is more useful than routine expectorated sputum, and PCR positivity requires clinical interpretation',[
 ('Routine bacterial culture reliably grows Pneumocystis','Standard bacterial culture does not diagnose it.'),('A positive PCR always proves clinically significant pneumonia regardless of symptoms','Colonization and assay context matter.'),('A negative poorly collected expectorated sample excludes disease','Specimen type and sensitivity are important.')],
 'A diagnostic result depends on the specimen and method', '**Organism stains and validated molecular tests can establish evidence in suitable respiratory samples.**',['BAL is often more sensitive than induced sputum.','Beta-D-glucan is supportive but not specific for PCP.'], '**Match the result to the clinical and imaging syndrome.**',['Severe high-probability disease may require treatment before confirmation.','Assess alternative or additional diagnoses if response is atypical.'],[['Specimen','Induced sputum or BAL'],['PCR','Sensitive but clinically contextual'],['Beta-D-glucan','Supportive, nonspecific']],[PC])
q('A patient with HIV, CD4 40 and positive Toxoplasma IgG has headache and multiple enhancing brain lesions, including basal-ganglia lesions. What is the leading diagnosis?', 'Toxoplasma encephalitis',[
 ('Progressive multifocal leukoencephalopathy','It typically produces nonenhancing white-matter lesions without this mass-lesion pattern.'),('Cryptococcal meningitis as the only explanation','It more commonly presents as a meningitic illness rather than this pattern.'),('Primary CNS lymphoma is excluded by multiple lesions','It remains a competing diagnosis, although the total presentation favors toxoplasmosis.')],
 'Reactivation produces focal cerebral disease in advanced immunodeficiency', '**Toxoplasma encephalitis commonly causes focal deficits and enhancing lesions.**',['IgG positivity supports prior exposure rather than proving active disease.','Lymphoma and other infections remain important differentials.'], '**Start appropriate therapy and assess clinical response.**',['Use MRI and specialist assessment to guide the pathway.','Biopsy may be needed when the pattern or response is atypical.'],[['Toxoplasma','Often multiple enhancing lesions'],['PML','Usually white-matter demyelination'],['Lymphoma','Important competing mass lesion']],[TO],style='clinical_scenario')
q('Which person with HIV has a clear indication for primary Toxoplasma prophylaxis?', 'A Toxoplasma-IgG-positive person with CD4 below 100 cells/mm3',[
 ('Every IgG-negative person with CD4 700','This is not the primary reactivation-prophylaxis indication.'),('Every person with isolated positive IgM regardless of confirmation or immune status','IgM interpretation is not the prophylaxis criterion.'),('Only patients who already have encephalitis','That concerns treatment and secondary prophylaxis, not primary prevention.')],
 'Reactivation risk depends on prior infection and cellular immunity', '**IgG identifies previous exposure relevant to reactivation.**',['TMP-SMX can cover both Toxoplasma and PCP prevention.','Some PCP-only alternatives do not protect against Toxoplasma.'], '**Choose prophylaxis that fits both risks.**',['Review allergy and safety requirements for alternatives.','Reassess after effective ART and immune recovery.'],[['IgG positive','Prior exposure'],['CD4 <100','High reactivation-risk threshold'],['TMP-SMX','Dual preventive value']],[TO])
q('Why is leucovorin given with pyrimethamine-based treatment for toxoplasmosis?', 'To reduce pyrimethamine-associated bone-marrow toxicity',[
 ('To replace the need for an active companion anti-Toxoplasma drug','It is supportive folinic acid, not the antimicrobial companion.'),('To directly lower intracranial pressure','It does not have that action.'),('To prevent all sulfadiazine renal adverse effects','Hydration and appropriate monitoring address other risks.')],
 'Antifolate treatment can also affect host hematopoiesis', '**Leucovorin is folinic-acid rescue.**',['Pyrimethamine-containing regimens require it.','TMP-SMX is also a recommended treatment option in appropriate circumstances.'], '**Monitor the regimen rather than one drug in isolation.**',['Check blood count and organ function.','Assess clinical and radiological response and plan maintenance treatment.'],[['Pyrimethamine','Antifolate antimicrobial'],['Leucovorin','Reduces marrow toxicity'],['Monitoring','Blood counts and clinical response']],[TO])
q('A patient treated adequately for presumed Toxoplasma encephalitis has no clinical improvement after 14 days. What is the best next principle?', 'Reassess the diagnosis, treatment delivery and need for brain biopsy',[
 ('Continue the same empirical diagnosis for months without review','Failure to improve should prompt further investigation.'),('Assume every persistent lesion is harmless immune recovery','Alternative disease or inadequate treatment must be considered.'),('Give corticosteroids solely to make all lesions disappear before diagnosis','Steroids can obscure lymphoma diagnosis and are used for selected clinical indications.')],
 'A therapeutic trial requires a defined reassessment point', '**Clinical improvement is expected in most responding cases within 10–14 days.**',['Earlier deterioration also warrants urgent review.','CNS lymphoma and other infections can mimic toxoplasmosis.'], '**Check adherence, absorption, dosing and complications.**',['Use repeat imaging and specialist review.','Obtain tissue when indicated rather than extending an unsupported diagnosis.'],[['Response window','Often evident by 10–14 days'],['Nonresponse','Reconsider diagnosis and delivery'],['Confirmation','Biopsy when indicated']],[TO],style='clinical_scenario')

